import org.json.JSONObject
import org.json.JSONArray
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder

var currentAccessToken = "YOUR_USER_ACCESS_TOKEN"
class ApiError(val status: Int, val data: JSONObject, val retryAfter: String?) :
    Exception(data.optString("message", "HTTP $status"))

// Blocking: run on an IO/background thread. Do not log tokens or responses.
fun requestJson(url: String, body: String, contentType: String = "application/json"): JSONObject {
    val connection = URL(url).openConnection() as HttpURLConnection
    try {
        connection.requestMethod = "POST"
        connection.connectTimeout = 15000
        connection.readTimeout = 30000
        connection.instanceFollowRedirects = false
        connection.doOutput = true
        if (!URL(url).path.startsWith("/auth/v1/oauth/")) {
            connection.setRequestProperty("Authorization", "Bearer $currentAccessToken")
        }
        connection.setRequestProperty("Content-Type", contentType)
        connection.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }
        val status = connection.responseCode
        val stream = if (status in 200..299) connection.inputStream else connection.errorStream
        val text = stream?.bufferedReader()?.use { it.readText() }.orEmpty()
        val data = try { JSONObject(text.ifBlank { "{}" }) }
            catch (_: Exception) { JSONObject().put("message", "HTTP $status: unexpected response") }
        if (status !in 200..299) throw ApiError(status, data, connection.getHeaderField("Retry-After"))
        return data
    } finally { connection.disconnect() }
}
fun api(endpoint: String, body: JSONObject = JSONObject()): JSONObject =
    requestJson("https://api.pocketpass.xyz/v1/$endpoint", body.toString())
fun form(values: Map<String, String>): String = values.entries.joinToString("&") {
    URLEncoder.encode(it.key, "UTF-8") + "=" + URLEncoder.encode(it.value, "UTF-8")
}
val session = api("session.get")
// Use session.getJSONArray("scopes") to decide which features to show.

